(window.NTDATA=window.NTDATA||{});(NTDATA.rbo=NTDATA.rbo||{}).prov={"1":{"1":"Притчи Соломона, сына Давидова, царя Израиля –","2":"тем, кто хочет постичь мудрость и наставление, и понять суть разумных изречений,","3":"усвоить правила благоразумия, праведности, справедливости и честности;","4":"простодушным – чтобы добавить им соображения, и юношам – ради знания и прозорливости;","5":"да и мудрый, услышав, приумножит знания, и разумный человек найдет подсказку,","6":"как понимать иносказания и притчи, изречения мудрецов и их загадки.","7":"Господа бояться – вот в чем начало познания! Кто презирает мудрость и наставление – глупец.","8":"Выслушай, сын, наставление отца и не отвергни материнского наказа;","9":"это – великолепный венец на главу твою, ожерелье тебе на шею.","10":"Сын мой, если поманят тебя грешники, не ходи.","11":"Они скажут: «Пойдем с нами, устроим засаду, убийство, подстережем невиновных!","12":"Мы, как Шеол, их живьем поглотим, целиком – как покойников могила.","13":"Всякого богатства награбим, наполним свои дома добычей;","14":"вместе с нами бросать будешь жребий, поровну разделим добычу!»","15":"Сын мой, с ними не ходи по дороге, на их путь ступить остерегайся,","16":"потому что бегут они ко злу и спешат к кровопролитию.","17":"Смысла нет раскидывать сеть на виду у порхающих птиц;","18":"так и они, подстерегая в засаде, погубят сами себя.","19":"Таков конец головореза: собственную голову он сложит.","20":"Премудрость на улице восклицает, на площадях возвышает голос;","21":"в шумной толпе взывает, у городских ворот держит речь:","22":"«Сколько можно простакам коснеть в простоте, наглым – наглостью тешиться, глупцам – ненавидеть знание?","23":"Обернитесь на мой упрек – изолью на вас мой дух и поведаю вам мое слово.","24":"Я позвала – а вы отвернулись; протянула руку – но никто не замечает.","25":"Вы отвергли все мои советы и не приняли моих упреков.","26":"Что ж, и я над вашей бедой посмеюсь, поиздеваюсь, когда настигнет вас ужас!","27":"Как буря, придет к вам ужас, и беда, как ураган, нагрянет; придавят вас гнет и бремя.","28":"Тогда позовут меня – и не отвечу, разыскивать будут – и не найдут.","29":"За то, что они возненавидели знание и отвергли страх Господень,","30":"не приняли мой совет, презрели все мои наставления, –","31":"вкусят они плоды своих дел, замыслами своими насытятся.","32":"Потому что простаков погубит своенравие, глупцов подведет их беспечность.","33":"А кто слушает меня, будет жить спокойно, не страшась никакой беды»."},"2":{"1":"Сын мой, если примешь мои слова и мои наказы сохранишь в душе,","2":"склонишь слух к мудрости и сердце обратишь к разуму;","3":"если ты призовешь познание и к разуму будешь взывать;","4":"если будешь желать его, как серебра, и будешь искать, словно клад, –","5":"то постигнешь страх Господень и обретешь познание Бога.","6":"Ибо Господь дает мудрость, и от уст Его – знание и разум;","7":"Он приготовил победу для честных и щит для живущих непорочно.","8":"Он хранит пути справедливости и дорогу верных бережет.","9":"Тогда постигнешь праведность, справедливость и прямоту всех добрых путей.","10":"Ибо войдет к тебе в сердце мудрость и знание усладит твою душу.","11":"Прозорливость будет оберегать тебя, разум будет тебя хранить,","12":"чтобы избавить от дурного пути, от человека, чьи речи бесчестны;","13":"от людей, что сходят с прямых дорог, чтобы идти путями тьмы,","14":"радуются злодеяниям, наслаждаются злом и развратом","15":"и по кривым стезям, по следам своим кружат.","16":"Так убережешься ты от чужой жены, от замужней с ее ласковой речью –","17":"от той, что покинула друга юности своей и завет Бога своего забыла.","18":"Ибо ее дом – смертельная ловушка, путь ее ведет к теням подземным.","19":"Кто к ней вошел, не вернется назад и уже не ступит на путь жизни.","20":"Поэтому ходи дорогой добрых, пути праведников держись.","21":"Ибо кто честен – будет жить на земле, и кто непорочен – останется на ней.","22":"А нечестивцев отвергнет земля, и неверные будут искоренены."},"3":{"1":"Сын мой, моего учения не забывай и мой наказ сохрани в сердце.","2":"Ибо это продлит тебе дни и годы, благоденствие твое умножит.","3":"Да не покинут тебя вера и правда: надень их, как ожерелье, на шею, запиши на скрижаль сердца –","4":"и будут тебе милости и почести от Бога и от людей.","5":"Господу доверься всем сердцем, на собственный разум не полагайся.","6":"Каким бы путем ни шел, познавай Господа, и выпрямит Он твои стези.","7":"Не считай себя мудрецом, бойся Господа, сторонись зла –","8":"это будет целительно для твоего тела и прибавит силы костям твоим.","9":"Уделяй Господу от своего достояния и от первых плодов любого дела,","10":"и наполнятся твои кладовые изобилия, переполнит давильни молодое вино.","11":"Наставления Господня, сын мой, не отвергай, от упреков Его не отвращайся.","12":"Ведь Господь порицает того, кого любит, как отец – драгоценного сына.","13":"Счастлив человек, обретший мудрость, человек, достигший разумения.","14":"Лучше мудрость обрести, чем серебро, ибо она золота ценнее,","15":"дороже она, чем самоцветы, ничто желанное с ней не сравнится.","16":"В правой руке у нее – долголетие, а богатство и почет – в левой.","17":"Дороги ее – дороги радости, все ее пути благополучны.","18":"Она – древо жизни для тех, кто ей привержен, и блажен, кто с ней неразлучен.","19":"Господь мудростью основал землю, небеса утвердил разумом,","20":"Его ведением разверзаются бездны, и облака источают росу.","21":"Сын, да не скроется это от тебя, и сохранишь благоразумие и прозорливость.","22":"И будет это жизнью для твоей души, и станет людская милость твоим ожерельем.","23":"Тогда безопасна будет твоя дорога, и нога твоя не оступится.","24":"Ляжешь спать без боязни, заснешь – и сон будет сладок.","25":"Не бойся внезапного несчастья, погибели, что готовят нечестивцы;","26":"ибо Господь – на твоей стороне, Он не даст тебе ступить в западню.","27":"Не скрывай добра от законного владельца, если это в твоей власти;","28":"не говори ближнему: «Ступай, придешь потом, завтра дам», – если есть, чем поделиться.","29":"Не замышляй ничего против человека, который тебе доверяет.","30":"Не ссорься попусту с тем, кто не причинил тебе зла.","31":"Не завидуй творящему насилие и не выбирай его дороги,","32":"ибо мерзок Господу коварный, а честные – у Него в доверии.","33":"Проклятие Господа – на доме нечестивца; а жилище праведных Он благословляет.","34":"Над насмешниками Он посмеется, а кротким дарует милость.","35":"Мудрые обретут славу, а глупцы погрязнут в позоре."},"4":{"1":"Слушайте, сыновья, наставление отца, внимайте, набирайтесь ума.","2":"Ведь я учу вас добру, не пренебрегайте наказом моим.","3":"Были отец с матерью и у меня, был и я для них любимцем ненаглядным.","4":"Вот как отец поучал меня: сохрани в сердце мои слова, соблюдай заветы мои – и будешь жить.","5":"Приобретай мудрость, обретай знание, не забывай и не отвергай того, что сказал я.","6":"Не покидай мудрости – и она сохранит тебя, люби ее – и она обережет тебя.","7":"В чем начало мудрости? Обретай мудрость, что бы ты ни копил, накопи разумение.","8":"Оцени мудрость – и она вознесет тебя, прославит тебя, если обнимешь ее.","9":"Великолепный венок на главу возложит, принесет тебе сияющий венец.","10":"Выслушай, сын, и прими мои слова – и продлятся годы твоей жизни.","11":"Путь мудрости укажу тебе, направлю дорогой прямой.","12":"Пойдешь – не собьется шаг, и если побежишь, не споткнешься.","13":"Держись этих правил, не отступайся, храни их, ибо в них – твоя жизнь.","14":"На дорогу нечестивых не вступай, не следуй по пути злодеев:","15":"сверни с него, не ходи по нему, пройди стороной, ступай мимо.","16":"Ведь им не спится, если не сотворили злодейства, глаз они не сомкнут, если кого не погубили.","17":"Ведь питаются они злодейством, как хлебом, и пьют насилие, как вино.","18":"Путь благочестивых – как свет зари, что разгорается ярче с приходом дня.","19":"А путь нечестивых – во мраке, и неведомо им, где споткнутся.","20":"Сын, прислушайся к моим словам, к речам моим будь внимателен.","21":"Да не ускользнут они от тебя, сохрани их в глубине сердца.","22":"Ибо станут они жизнью для того, кто обрел их, будут для плоти целительны.","23":"Оберегай свое сердце пуще сокровищ, потому что оно – источник жизни.","24":"Отвергни лживые слова, лукавство от уст своих гони;","25":"пусть глаза твои смотрят прямо, пусть будет взгляд устремлен вперед.","26":"Прямо прокладывай свою дорогу, и все пути твои будут безопасны;","27":"не уклоняйся ни вправо, ни влево, отступись от зла."},"5":{"1":"Сын, выслушай мою мудрость, в мысли мои вникай –","2":"чтобы исполниться прозорливости, чтобы знание твои уста хранили.","3":"Источают мед уста чужой жены, и текут, как масло, ее речи –","4":"обернется она горечью полынной, лезвием меча обоюдоострого.","5":"Ее стопы спускаются к смерти, шаги направлены к Шеолу.","6":"О дороге жизни она не помыслит, как зыбки ее пути, сама не знает.","7":"Так послушайте меня, дети, и слов моих не отвергайте.","8":"Держись от нее подальше, к порогу ее не приближайся,","9":"а не то потратишь на чужих свою силу, на безжалостных – годы своей жизни;","10":"твоей силой насытятся другие, чужому дому пойдут твои старания.","11":"И вздохнешь ты в конце своей жизни, когда плоть твоя увянет и иссохнет:","12":"«Зачем пренебрегал я наставлениями и упреки отвергало мое сердце,","13":"зачем я учителей не слушал и наставникам не внимал?","14":"Еще шаг – и меня опозорят пред людьми, при всем народе».","15":"Пей из своего водоема, черпай из своего колодца.","16":"Зачем твоим водам проливаться на улицах, растекаться по площадям?","17":"Оставь их себе одному, не дели с чужими.","18":"Да будет благословен твой родник, да будет в радость жена юности твоей.","19":"Лань любимая, козочка милая – ее грудь утолит тебя во всякое время, любовь к ней пьянит тебя непрестанно.","20":"И зачем, сын мой, опьяняться чужой женой, обнимать стан замужней?","21":"Ведь открыты Господу все пути человека, все дороги людские Он ведает.","22":"Нечестивый попадет в сети зла своего, запутается в собственных грехах.","23":"Погубит его недостаток воспитания, избыток глупости с пути собьет."},"6":{"1":"Сын мой! Если ты поручился за другого, за чужого поруку дал –","2":"то на собственном слове ты попался, собственным словом был пленен.","3":"Что угодно делай, сын, но избавься, ибо ты теперь в чужой власти. Падай в ноги, умоляй, не отставай,","4":"гони от себя сон, глаз не смыкай,","5":"спасайся, как газель от погони, как птица от ловца.","6":"Лентяй! Ступай к муравью, поучись у него мудрости:","7":"нет над ним ни вождя, ни старосты, ни правителя;","8":"а он с лета запасается пищей и в жатву копит припасы.","9":"Сколько можно лежать, лентяй, не пора ли от сна очнуться?","10":"Еще чуть поспишь, подремлешь, еще посидишь сложа руки –","11":"и придет к тебе бедность, как бродяга, нагрянет нужда, как грабитель.","12":"У негодяя и злодея ложь с уст не сходит:","13":"то он подмигнет, то ногой притопнет, то пальцами знак подаст.","14":"В его сердце – порок, в его мыслях – зло, раздоры он разжигает.","15":"За это нагрянет к нему беда, погубит нежданно и безвозвратно.","16":"Шесть вещей ненавидит Господь, и седьмая для Него – мерзость:","17":"заносчивый взгляд, лживый язык, руки, проливающие невинную кровь,","18":"сердце, что замышляет злодейство, ноги, спешно бегущие ко злу,","19":"лжесвидетель, дышащий ложью, и тот, кто сеет раздоры меж братьями.","20":"Сын! Храни отцовский завет и не отвергай материнского наказа.","21":"Носи их всегда в своем сердце, надень, как ожерелье, на шею.","22":"Пойдешь – они поведут тебя, ляжешь спать – будут хранить тебя, проснешься – заговорят с тобой.","23":"Ибо заповедь – светильник, учение – свет, а строгое наставление – путь жизни.","24":"Они уберегут тебя от дурной женщины, от льстивых речей чужой жены.","25":"Не тревожь свое сердце ее красотой, не пленяйся взмахом ее ресниц.","26":"Ведь блуднице цена – ломоть хлеба, а за чужую жену заплатишь жизнью.","27":"Можно ли скрыть огонь за пазухой и не подпалить одежду?","28":"Можно ль пройти по горящим углям и не обжечь ног?","29":"Так и с тем, кто ходит к чужой жене: не останется безнаказанным, кто ее коснулся.","30":"Не строго судят вора, что украл с голоду, чтобы только поесть;","31":"а все ж поймают – возместит всемеро, все свое имущество отдаст.","32":"Недостает ума прелюбодею – готовит он собственную гибель.","33":"Побои и бесчестье ожидают его, и позор несмываемый.","34":"Ибо ревность сжигает мужа, и он не пощадит в день мести,","35":"не согласится ни на какой выкуп, не смягчится, сколько ему ни сули."},"7":{"1":"Сын, храни мои слова и мои наказы береги.","2":"Соблюдай мои заветы – и будешь жить, мой наказ береги, как зеницу ока.","3":"Носи их, как перстень, запиши на скрижали сердца.","4":"Скажи мудрости: «Ты мне сестра!», и с разумением породнись.","5":"Так убережешься ты от чужой жены, от замужней с ее ласковой речью.","6":"Как-то выглянул я в свое окно, посмотрел сквозь оконную решетку","7":"и увидел среди простаков, заметил среди молодых одного юнца неразумного.","8":"Он бродил по улице, где она живет, направлялся к ее дому –","9":"в сумерках на закате дня, под покровом ночи, во тьме.","10":"А навстречу ему женщина – в одежде блудницы, с лукавым сердцем,","11":"неугомонная и дерзкая, и дома ей не сидится:","12":"то она на улице, то на площадях, за каждым углом подстерегает.","13":"Ухватилась она за него, поцеловала и с бесстыдным видом говорила:","14":"«Я пиршественные жертвы принесла, я сегодня исполнила обеты.","15":"Потому я и вышла тебе навстречу, искала тебя – и нашла.","16":"Покрывала постелила я на ложе, цветные египетские ткани.","17":"Надушила постель миррой, алоэ и киннамоном.","18":"Приди, натешимся ласками до утра, сполна насладимся любовью.","19":"Ведь мужа нет дома: он отправился в дальний путь,","20":"захватил кошель с деньгами, не вернется домой до полнолуния».","21":"Обольстила его множеством уловок, ласковою речью заманила.","22":"И тотчас пошел он за нею, как бык идет на убой, как олень ступает в ловушку,","23":"где стрела пронзит ему печень; как птица летит в силок, не зная, что поплатится жизнью.","24":"Так вот, послушайте меня, дети, внимайте моим словам:","25":"да не свернет ваше сердце на ее дорогу, не блуждайте по ее путям!","26":"Ведь многие пали ее жертвой, немало людей она погубила.","27":"Ее дом – это путь в Шеол, дорога к обителям смерти."},"8":{"1":"Не Премудрость ли это зовет, не ее ли разумный голос слышен?","2":"На вершине холма над дорогой, на перепутье она стоит;","3":"у ворот городских взывает, при входе в город восклицает:","4":"«Вас, люди, зову я, мой призыв – к сынам человеческим!","5":"Простаки, научитесь проницательности, глупцы, наберитесь ума!","6":"Слушайте мою возвышенную речь, ибо правда у меня на устах,","7":"истину вещает мой язык, и мерзко устам моим зло.","8":"Праведны все мои речи, ни лукавства в них, ни обмана;","9":"все они для разумного открыты, доступны для ищущих знания.","10":"Цените мое наставление выше серебра, знание – выше червонного золота.","11":"Ибо мудрость – прекрасней самоцветов, ничто желанное с ней не сравнится.","12":"Я – Премудрость, и со мною проницательность, знание и прозорливость я обрела.","13":"Страх Господень – это ненависть ко злу Гордость и заносчивость, путь зла и лживые уста я ненавижу.","14":"У меня – совет, у меня – успех, я – разум, и со мною сила.","15":"Мною царствуют цари и властители устанавливают справедливость,","16":"мною вершат правление вожди, князья и все судьи земли.","17":"Кто любит меня, того и я люблю, и кто ищет меня – найдет.","18":"Богатство и слава – со мною, нескончаемое процветание и правда.","19":"Лучше золота червонного мои плоды, я ценнее чистого серебра.","20":"Я ступаю по пути праведности, по стезям справедливости,","21":"чтобы любящих меня наградить достойно и сокровищницы их наполнить.","22":"Господь сделал меня началом пути Своего, прежде всех Своих деяний, издревле.","23":"Я возникла от начала времен, издревле, при основании мира.","24":"Прежде первозданной бездны и источников вод я появилась;","25":"еще не были воздвигнуты горы и холмы, когда я возникла,","26":"еще не создал Он тогда земных просторов и первой горсти земного праха!","27":"Когда Он утверждал небеса – я там была, когда чертил круг на поверхности бездны,","28":"когда Он водружал облака наверху, когда укреплял источники бездны,","29":"когда Он полагал морю предел, которого не преступят воды, когда устанавливал основания земли –","30":"я была при Нем строительницей, была ежедневным ликованием, веселилась пред Ним непрестанно –","31":"веселилась о мире земном и ликовала о сынах человеческих.","32":"А теперь послушайте меня, дети: блажен, кто держится моих путей!","33":"Слушайте наставление – и будете мудры, не отвергайте его.","34":"Блажен, кто слушает меня, у порога моего днюет и ночует, с двери моей глаз не сводит.","35":"Кто обрел меня – обрел жизнь и снискал благоволение у Господа.","36":"А кто против меня, сам себя губит: ненавидеть меня – значит любить смерть»."},"9":{"1":"Премудрость построила себе дом, семь столпов поставила тесаных,","2":"приготовила мяса и пряных вин, накрыла на стол.","3":"И послала служанок возглашать с высот городских во всеуслышание:","4":"«Простаки, обратитесь ко мне!» Несмышленым она сказала:","5":"«Приходите, ешьте мои яства, пейте пряные мои вина!","6":"Распрощайтесь с невежеством – и будете жить, и идти путем разума.","7":"Поправишь наглеца – не миновать оскорбления, упрекнешь нечестивца – лишь себе на позор.","8":"Не упрекай наглеца, а не то возненавидит тебя, упрекай мудреца, и он тебя полюбит.","9":"Мудрого наставь – он станет еще мудрее, научи праведного – еще разумнее будет.","10":"Господа бояться – вот начало мудрости, Его святость познавать – вот в чем разум!","11":"Со мной, Премудростью, продлятся твои дни и умножатся годы жизни.","12":"Если ты мудр, твоя мудрость служит тебе, если нагл – сам же и пострадаешь».","13":"Глупость – женщина дерзкая, неотесанная, невежественная –","14":"восседает у дверей своего дома, как на троне, на виду у всего города,","15":"чтобы звать всех проходящих мимо, идущих своей дорогой:","16":"«Простаки, обратитесь ко мне!» Несмышленому она говорит:","17":"«Краденая вода слаще, утаенный хлеб вкуснее!»","18":"А тот и не знает, что зовут его к теням, что гости ее – в глубинах Шеола."},"10":{"1":"Изречения Соломона. Мудрый сын – на радость отцу, а сын глупый – матери на горе.","2":"Прока нет в неправедном богатстве, а праведность спасает от смерти.","3":"Не оставит Господь праведника голодным, но отвергнет алчущего нечестивца.","4":"От ленивых рук – разорение, а от прилежных – богатство.","5":"Кто потрудится летом – молодец, а кто жатву проспит, тому позор.","6":"Благословениями праведник увенчан, а уста нечестивых таят насилие.","7":"Память о праведнике благословенна, но даже имя нечестивого сгинет.","8":"В сердце мудреца хранятся заповеди, а уста глупца доведут до беды.","9":"Кто идет прямой дорогой, тот спокоен, а кто петляет – тот и попадется.","10":"Перемигивания вызовут обиду, а уста глупца доведут до беды.","11":"Уста праведника – живительный родник, а уста нечестивых таят насилие.","12":"Ненависть раздоры раздувает, а любовь загладит все грехи.","13":"На устах разумных обитает премудрость, а для спины глупых найдется розга.","14":"Мудрецы берегут познание, а речи глупца ведут к разорению.","15":"Для богатого достаток – словно крепость, а для бедных нищета – как пепелище.","16":"Труды праведного – ради жизни, но нажива нечестивца – для греха.","17":"Следовать наставлениям – вот путь жизни, а если пренебрегаешь упреками, заблудишься.","18":"Лживые уста таят вражду, разносчик сплетен – глуп.","19":"При многословии не миновать греха, а кто скуп на слова, тот разумен.","20":"Язык праведника – что отборное серебро, а много ли стоит сердце нечестивца?","21":"Слова праведного оберегают многих, а глупцов губит собственная дурость.","22":"Благословение Господне тебя обогатит, ты с ним горя знать уже не будешь.","23":"Глупца радует пакость, а проницательного – мудрость.","24":"Сбудутся страхи нечестивых, и желания праведных исполнятся.","25":"Буря пройдет – и нет нечестивца, но праведник крепок вовеки.","26":"Как уксус во рту, как дым в глаза – так и лодырь для того, кто с ним связался.","27":"Кто Господа боится – живет долго, но годы нечестивых сочтены.","28":"Радостны упования праведных, но погибнет надежда нечестивых.","29":"Путь Господень для непорочного – прибежище, а для злодея – ужас.","30":"Непоколебим вовеки праведник, а нечестивым на земле не удержаться.","31":"Уста праведника источают мудрость, а зловредный язык будет отрезан.","32":"Устам праведника ведомо полезное, а устам нечестивых – зловредное."},"11":{"1":"Лживые весы мерзки Господу, а верные гири Ему угодны.","2":"За дерзостью по пятам идет позор, а за смирением следует мудрость.","3":"Прямодушных ведет их непорочность, а вероломных губит их коварство.","4":"Не поможет богатство в День Гнева, но праведность избавит от смерти.","5":"Праведность и непорочность ведут прямой дорогой, а нечестивец падет в своем злодействе.","6":"Праведность спасает прямодушных, а вероломные – в силках своих желаний.","7":"Вместе с нечестивцем умрет его надежда, ожидания людей недобрых сгинут.","8":"Праведник избежит беды, а попадает в нее нечестивец.","9":"Уста безбожника погубят ближнего, а праведных избавит познание.","10":"Хорошо праведнику – и радуется город, погибли нечестивцы – ликует.","11":"Благословениями честных возводится город и рушится речами нечестивцев.","12":"Глупец бесчестит ближнего, а кто понимает – промолчит.","13":"Сплетник раскрывает чужие секреты, а верный человек и словом не обмолвится.","14":"Без наставления народ погибнет, а если советников достаточно – спасется.","15":"Дав поруку за чужого, не минуешь беды, но кто не спешит ручаться – избежит ее.","16":"Женщина кроткая, милая обретает славу, а властители стяжают богатство.","17":"Добродетельный приносит себе пользу, а жестокий на себя же навлекает беду.","18":"Награда злодею обманчива, а тому, кто сеет правду, – наградой истина.","19":"Праведность – это жизнь, а кто гонится за злом, стремится к смерти.","20":"Мерзки Господу люди криводушные и угодны те, чей путь непорочен.","21":"Будь уверен: злодею не оправдаться, но род праведных спасется.","22":"Что золотое кольцо в свином рыле, то и краса женщины безрассудной.","23":"Чаяния праведных обернутся добром, а надежды нечестивых – гневом Божьим.","24":"Один раздает – и у него прибавляется, а другой жадничает – и у него недостает.","25":"Кто щедр, тот будет в достатке, кто дал другому пить, не будет жаждать.","26":"Кто припрячет зерно, того проклянут, но благословен будет продающий.","27":"Кто ищет добра, найдет благоволение, а кто стремится к злу, на себя его накличет.","28":"Кто полагается на свое богатство – падет, а праведники будут как зеленеющее дерево.","29":"Кто на свой дом навлекает беду, тому удел – ветер, и станет глупец слугой мудрому.","30":"От плода праведности вырастает древо жизни, и мудрец покоряет сердца людей.","31":"Если праведнику на земле воздастся, то нечестивцу, грешнику – и подавно."},"12":{"1":"Кто любит познание – любит и наставление, а кто отвергает упреки – скудоумен.","2":"Добрый обретает у Господа благоволение, а коварного постигнет злая участь.","3":"Злодею на земле не устоять, а праведники неискоренимы.","4":"Достойная жена – венец для супруга, а бесстыжая – словно гниль в костях.","5":"Праведник помышляет о справедливости, а нечестивец затевает коварство.","6":"За словами нечестивца – жажда крови, а правдивые речи спасительны.","7":"Пал нечестивец – и нет его, а дом праведника устоит.","8":"Речь разумная прославит человека, а порочные замыслы опозорят.","9":"Лучше в простоте и быть самому себе слугой, чем со спесью, да без крошки хлеба.","10":"Праведник и скотину пожалеет, но милость нечестивца – хуже жестокости.","11":"Кто возделывает землю, будет сыт, а глупец за пустотой гоняется.","12":"Нечестивец изощряется в коварстве, но корень праведных дает побеги.","13":"Нечестивец в лживых речах запутается, а праведник избежит беды.","14":"Человек пожнет добрый плод своих речей, возвратятся труды к нему наградой.","15":"Глупец считает свой путь правильным, а мудрый прислушивается к советам.","16":"Глупец выставляет свой гнев напоказ, а разумный не слушает оскорблений.","17":"Слова честного человека правдивы, а слова лжесвидетеля – коварны.","18":"Болтовня может ранить, как меч, а слова мудрецов – исцеляют.","19":"Правдивые слова останутся навеки, а лживый язык недолговечен.","20":"У злокозненных на сердце коварство, а у миротворцев – радость.","21":"Не приключится с праведником несчастья, а нечестивых зло переполняет.","22":"Лживые уста – мерзость для Господа, но угоден Ему тот, кто поступает честно.","23":"Проницательный таит свое знание, а глупцы выставляют свою дурь напоказ.","24":"Прилежной руке – править, ленивой руке – нести повинность.","25":"Беспокойство изнуряет сердце человека, а доброе слово – веселит.","26":"Праведник укажет путь ближнему, а на стезях нечестивцев заблудишься.","27":"Лодырю добычи не видать, а у прилежного – богатство и достаток.","28":"Стезя правды – к жизни, а кривые пути – к смерти."},"13":{"1":"Мудрость сына – от отцовских наставлений, а наглец упреков не слышит.","2":"Человек вкусит добрый плод своих речей, а коварные живут насилием.","3":"Кто свои уста стережет – жизнь сбережет, а кто несдержан на язык – себя погубит.","4":"Лентяй все ждет, да не дождется, зато прилежный насытится.","5":"Ненавидит праведник любую ложь, а нечестивец осрамится, опозорится.","6":"Праведность выведет на прямую дорогу, а нечестие грешника с пути собьет.","7":"Один, ничего не имея, притворится богачом, а другой, при богатстве немалом, – бедняком.","8":"Богатство сохранит человеку жизнь, зато бедный упрека не услышит.","9":"Свет праведных радостно горит, а светильник нечестивых гаснет.","10":"От надменности – только ссоры, а где совет, там и мудрость.","11":"Шальное богатство рассеется, а по крупице собранное – приумножится.","12":"Несбывшаяся надежда – боль сердца, а исполненное желание – древо жизни.","13":"Кто сказанным пренебрежет – себя погубит, а кто почитает заповедь – получит награду.","15":"Учение мудреца – источник жизни, оно сберегает от сетей смерти.","16":"Здравый разум одаряет милостью, а путь коварства ведет к погибели.","17":"Проницательный действует с умом, а глупец свою дурь выказывает.","18":"Дурному вестнику несдобровать, а верный гонец несет исцеление.","19":"Нищета и бесчестье тому, кто отверг назидание, а тому, кто принял наставление, почет.","20":"Исполнение желаний услаждает душу; хуже нет для глупца, чем расстаться со злом.","21":"С мудрецами общаясь, станешь мудрее, а повелся с глупцами – не минуешь беды.","22":"За грешником ходит беда, а праведнику воздается добром.","23":"Богатство достойного пойдет детям и внукам, а что нажил грешник – праведнику достанется.","24":"Пусть и обилен урожай бедняка, беззаконие его похитит.","25":"Кому жалко розгу, не жалко сына, а кто сына любит, не забудет вразумить.","26":"Праведник ест досыта, а в животе у нечестивых пусто."},"14":{"1":"Мудрая женщина возводит дом, а женщина глупая – сама его рушит.","2":"Кто боится Господа, ступает прямо, а кто Его презирает – петляет.","3":"Болтовня гордеца – это плеть для него, а речи мудрецов – защита для них.","4":"Нет волов – и пусты закрома, а при могучих быках урожай обилен.","5":"Верный свидетель не обманет, а нечестный свидетель дышит ложью.","6":"Ищет наглец мудрости, да не сыщет, а разумному легко дается знание.","7":"Держись подальше от глупца, умных слов от него не дождешься.","8":"Мудрость прозорливого – в понимании своего пути, а неразумие глупцов – в их обманах.","9":"Глупцы смеются над искупительными жертвами, но благоволение Господне – с честными.","10":"Только сердце человека знает его печали, и радости его другим не разделить.","11":"Дому нечестивых – разрушение, шатру честных – процветание.","12":"Иной путь и кажется прямым, но в конце концов приводит к смерти.","13":"Бывает, среди веселья опечалится сердце, и за радостью настает печаль.","14":"К чему шел порочный – то он и получит, а хорошему человеку воздастся за труды.","15":"Легковерный всякому слову доверится, осмотрительный перед каждым шагом подумает.","16":"Мудрый страшится и чурается зла, зато глупец буянит, ничего не боится.","17":"Кто скор на гнев – натворит глупостей, кто коварен – того возненавидят.","18":"Удел простаков – глупость, венец проницательных – знание.","19":"Злодеи склонятся перед добрыми людьми, и нечестивцы – перед воротами праведника.","20":"Бедняком даже сосед гнушается, зато богача любят многие.","21":"Кто презирает соседа – грешит, но блажен, кто заботится о несчастных.","22":"Кто зло замышляет – собьется с пути; вера и правда – с тем, кто творит добро.","23":"От упорных трудов – всегда прибыток, от пустословия – лишь нужда.","24":"Венец мудрецов – их богатство, украшение глупцов – их дурь.","25":"Верный свидетель спасает жизни, а коварный – дышит ложью.","26":"Страх Господень – надежная защита, прибежище тебе и твоим детям.","27":"Страх Господень – источник жизни, он сберегает от сетей смерти.","28":"Царь велик, когда подданных много, а редеет народ – погибает владыка.","29":"Кто не скор на гнев, тот разумен, а кто вспыльчив – выказывает дурь.","30":"Сердце спокойно – тело здорово, а зависть и ревность – что гниль для костей.","31":"Кто притесняет бедняков, оскорбляет их Творца, но кто заботится о нищих, прославляет Его.","32":"Зло нечестивцев на них же и падет, а праведника защитит его непорочность.","33":"Премудрость живет в разумном сердце, и среди глупцов она заметна.","34":"Праведностью велик народ, а грех подтачивает его.","35":"Царь благоволит разумному рабу и гневается на того, чьи дела постыдны."},"15":{"1":"Кроткий ответ отвращает гнев, резкое слово вызывает ярость.","2":"Язык мудрецов распространяет знания, а от уст глупцов лишь дурость исходит.","3":"Очи Господни все видят, взирают и на злых, и на добрых.","4":"Умиротворяющая речь – древо жизни, а речь обманчивая сокрушает дух.","5":"Глумится глупец над отцовским внушением, но кто внимает упрекам – поумнеет.","6":"В доме праведника много сокровищ, а нечестивцу прибыток не на пользу.","7":"Уста мудрецов распространяют знание, но не так поступают глупцы.","8":"Мерзки Господу жертвы нечестивых, а молитвы честных Ему угодны.","9":"Мерзок Господу путь нечестивца, а того, кто ищет праведность, Он любит.","10":"Кто сбился с пути, будет сурово наказан; кто ненавидит наставления – погибнет.","11":"Шеол и Аваддон открыты Господу – тем более сердца человеческие!","12":"Не любит наглец укоров и не задержится среди мудрецов.","13":"Сердце радостно – светлеет лицо, а скорбное сердце сокрушает дух.","14":"Разумное сердце ищет знания, а глупцы питаются дуростью.","15":"У бедняка что ни день, то невзгоды, а у кого на сердце весело, у того всегда пир.","16":"Лучше иметь немногое и бояться Господа, чем обладать сокровищами и жить в страхе.","17":"Лучше обед из овощей, да с любовью, чем из откормленного теленка, да с ненавистью.","18":"Вспыльчивый человек сеет раздоры, а терпеливый кладет конец вражде.","19":"Путь лентяя зарос колючками, а праведные идут по широкой дороге.","20":"Мудрый сын радует отца, а глупец позорит мать.","21":"Тешится дурью скудоумный, а разумный ступает прямо.","22":"Нет совета – не будет успеха в деле, а если советников достаточно – все выйдет.","23":"Радостно, если можешь ответить, и как хорошо уместное слово!","24":"Разумный поднимается по дороге жизни, прочь от глубин Шеола.","25":"Дома гордецов Господь сметет, но надел вдовы Он защитит.","26":"Мерзки Господу злые замыслы, а добрые слова пред Ним чисты.","27":"Корыстный на свой дом навлекает беду, а кто взяток не терпит – будет жить.","28":"Праведное сердце подскажет ответ, а уста нечестивые изрыгают зло.","29":"Далек Господь от нечестивцев, но молитву праведников слышит.","30":"Светлый взор радует сердце, добрая весть укрепляет кости.","31":"Кто внемлет здравым упрекам, неразлучен будет с мудрецами.","32":"Кто отвергает наставления – себе повредит, а кто внемлет упрекам, обретает разум.","33":"Страх Господень научит мудрости, славе предшествует смирение."},"16":{"1":"Сердце человека строит планы, но ответ на все – от уст Господних.","2":"Каждый считает свой путь непорочным, но Господь испытывает души.","3":"Вверяй Господу свои дела – и замыслы твои свершатся.","4":"Все создано Господом для своей цели, и нечестивец – для дня беды.","5":"Надменное сердце – мерзко Господу, ни за что не уйти ему от наказания.","6":"Вера и правда искупают вину, страх Господень отводит беду.","7":"Если угодны Господу пути человека, Он примирит с ним даже врагов.","8":"Лучше малость, да с праведностью, чем богатая прибыль, да с беззаконием.","9":"Человек избирает свой путь, но твердость шагам придает Господь.","10":"На устах царя – вещее слово, не ошибется он в своем приговоре.","11":"Верные чаши весов – от Господа, и гири в суме – творение рук Его.","12":"Мерзки царям нечестивые поступки, праведностью утвердится престол.","13":"Угодны царям праведные уста, люб им тот, кто говорит честно.","14":"Гнев царя – что ангел смерти, но мудрый человек и его успокоит.","15":"В светлом взоре царя – жизнь, благоволение его – как ливень весенний.","16":"Лучше знание копить, чем червонное золото, лучше разум обрести, чем чистое серебро.","17":"Дорога честных – в стороне от зла, кто с пути не собьется – жизнь сбережет.","18":"Несчастью предшествует гордыня, а падению – высокомерие.","19":"Лучше жить в смирении с бедняками, чем с гордецами делить награбленное.","20":"Кто рассудителен, обретет благополучие, и кто надеется на Господа обретет блаженство.","21":"Кто мудр сердцем, прослывет разумным, а сладость речей прибавит убедительности.","22":"Рассудительность – источник жизни, а наказание глупцу – его глупость.","23":"Разум мудреца подскажет ему слова и придаст убедительности его речам.","24":"Ласковая речь – что медовые соты: душе услаждение, телу исцеление.","25":"Иной путь и кажется прямым, но в конце концов приводит к смерти.","26":"Работник сам себе не даст передышки, когда подгоняет его голод.","27":"Негодяй изобретателен на зло, на устах его – словно пламя пышет.","28":"Коварный сеет раздоры, клеветник разлучает друзей.","29":"Злодей с пути сбивает ближнего и толкает его на путь недобрый.","30":"Кто щурится, тот замышляет превратное; кто губы кривит – творит дела дурные.","31":"Седина – сияющий венец, завершение праведного пути.","32":"Выдержка лучше богатырской мощи, кто владеет собой – сильней покорителя городов.","33":"Тянут из-за пазухи жребий, но всякое решение – от Господа."},"17":{"1":"Лучше черствая корка, да с миром, чем дом, где пиры да раздоры.","2":"Умный раб получит власть над недостойным сыном господина и наследство с его братьями разделит.","3":"Для плавки серебра – тигель, для золота – горнило, а для сердец – испытания от Господа.","4":"Злодей прислушивается к лукавым речам, и лжец внимает словам злокозненным.","5":"Кто глумится над бедняком, оскорбляет его Творца, и кто злорадствует, не уйдет от возмездия.","6":"Венец старцам – дети детей, а слава сынов – их отцы.","7":"Не пристала глупому важная речь, а благородному – речи лживые.","8":"Дающему взятка кажется волшебным камнем: куда ни поверни, всюду выгода.","9":"Кто стремится к любви, забывает обиду, а злопамятный теряет друга.","10":"Понятливого укор уязвит сильней, чем глупца – сотня тумаков.","11":"Злодей только к смуте стремится, и ангел неумолимый будет послан к нему.","12":"Лучше встретить медведицу, потерявшую детенышей, чем глупца, когда дурь в нем бушует!","13":"Кто злом воздает за добро – от его дома зло не отступится!","14":"Начало ссоры – как прорыв плотины, уймись, пока вражда не разбушевалась.","15":"Оправдать злодея, осудить невинного – и то, и другое Господу мерзко.","16":"К чему глупцу трясти мошной? Как купишь мудрость, если нет ума?","17":"Любовь друга – на все времена, и брат рожден, чтобы с братом беду разделить.","18":"Безрассудный тянет руку, спешит поручиться за другого.","19":"Кто любит свары – любит злодейство, кто превозносится – накличет падение.","20":"Лживому сердцу добра не видать, коварный язык доведет до беды.","21":"Кто породил глупца, родил себе горе: не порадуешься дури собственного сына.","22":"Радость на сердце – лучшее лекарство, а угнетенный дух иссушает тело.","23":"Нечестивец из-под полы берет взятку за то, что искажает правосудие.","24":"Проницательный взор обращен к Премудрости, а взгляд глупца – во все концы земли.","25":"Глупый сын – досада отцу и огорчение для матери.","26":"Дурное дело – взыскивать с невиновного или бить благородного за прямоту.","27":"Сведущий осторожен в словах, и кто разумен, тот хладнокровен.","28":"Глупец промолчит – и сойдет за мудреца, сомкнет уста – и кажется умным."},"18":{"1":"Кто живет сам по себе – творит, что хочет, а на здравые советы лишь бранится.","2":"Глупцу не нравится думать, зато любит он умом похваляться.","3":"По пятам за злодейством – презрение, а за бесчестием следует позор.","4":"Слова человека – глубокие воды, источник мудрости – струящийся поток.","5":"Дурное дело – потворствовать злодею или праведнику отказать в правосудии.","6":"Язык глупца доведет до ссоры, его уста накличут побои.","7":"В речах глупца – его погибель, его уста – для него же ловушка.","9":"Речи сплетника – что лакомство, проникают в самое нутро человека.","10":"Ленивый работник – все равно что разрушитель.","11":"Имя Господа – могучая башня: укроется в ней праведник и будет неприступен.","12":"Для богатого достаток – словно крепость, оно ему мнится стеной неприступной.","13":"Падению предшествует надменность, а славе – смирение.","14":"Давать ответ, не дослушав, – только глупость и стыд.","15":"Сильный духом справится с недугом, но как быть, если дух сломлен?","16":"Сердце разумного копит знание, ищет знания слух мудрецов.","17":"Подношения расчистят путь и откроют доступ к вельможам.","18":"В тяжбе кто первый, тот и прав – пока соперник не вступит в спор.","19":"Жребий улаживает споры и разводит могучих противников.","20":"Обиженный брат – неприступная крепость, а ссора – засов на воротах.","21":"Плодами своих речей насыщается человек: что добудет языком, тем и насытится.","22":"Жизнь и смерть – во власти языка, и кто с ним дружен, плоды его вкусит.","23":"Кто нашел жену – нашел сокровище и обрел благоволение Господне.","24":"В словах бедняка мольба, но грубость в ответе богача.","25":"У кого друзей много, тому несдобровать, но любовь иного друга – крепче братской."},"19":{"1":"Лучше бедняк, что живет непорочно, чем лжец, да к тому же глупец.","2":"Нет добра душе без познания, и торопливые ноги оступятся.","3":"Дурость сбивает человека с пути его, а сердце его на Господа злится.","4":"Богатство умножает число друзей, а бедность с друзьями разлучает.","5":"Не уйдет от возмездия лжесвидетель, и кто дышит ложью – не уцелеет.","6":"Многие заискивают перед знатными, и со щедрым на подарки всякий дружит.","7":"Ненавистен бедняк даже братьям, и друзья его избегают: спешит он слово молвить, а их уж нет!","8":"Кто желает себе добра, тот ищет разума: храня мудрость, обретет он благо.","9":"Не уйдет от возмездия лжесвидетель, и кто дышит ложью – погибнет.","10":"Не пристало глупцу жить в роскоши, а тем более рабу – князьями править.","11":"Благоразумие удержит от гнева, величие – в прощении проступков.","12":"Царская ярость – как рык львиный, а милость царя – как роса на траве.","13":"Глупый сын – несчастье для отца, а сварливая жена – что прореха в крыше.","14":"Дом и богатство – наследство от отцов, а разумная жена – дар от Господа.","15":"Лень доводит до сонной одури, а нерадивость – до голода.","16":"Хранящий заповедь сохраняет жизнь, а кто не разбирает пути – погибнет.","17":"Кто нищему подает – одалживает Господу, и Господь вернет ему сполна.","18":"Вразумляй сына, пока не поздно, смотри, не погуби его.","19":"Грубиян пусть понесет наказание, если дашь ему поблажку – будет хуже.","20":"Слушай советы, принимай наставления, и станешь со временем мудрее.","21":"Много замыслов в человеческом сердце, но исполнится то, что решил Господь.","22":"В людях ценится верность, и бедняк милей лжеца.","23":"Люди живы страхом Господним – кто исполнен им, спит спокойно, и беда его не постигнет.","24":"Запустит лодырь руку в блюдо, а до рта не донесет.","25":"Накажешь наглеца – простаки образумятся, отчитаешь разумного – он поймет твою науку.","26":"Кто груб с отцом, кто гонит мать – стыд и позор такому сыну!","27":"Сын! Не станешь слушать наставления – попадешь впросак без слов разумных.","28":"Негодный свидетель глумится над правосудием, преступление – пища для нечестивцев.","29":"Наглецу не миновать суда, а спине глупца – побоев."},"20":{"1":"Глумливо вино, и брага буйна, кто пристрастился к ним, тому мудрым не быть.","2":"Царская ярость – как рык львиный, навлечь ее – грех против себя самого.","3":"Почет тому, кто далек от ссоры, куда всякий глупец спешит ввязаться.","4":"Лодырь в холода не пашет, значит, в жатву ничего не сыщет.","5":"Сокровенный замысел – что глубокий омут, но разумный сумеет зачерпнуть из глубины.","6":"Многие кричат о своей преданности, но человека верного – найдешь ли?","7":"Праведник живет непорочно, блаженны его потомки!","8":"Воссядет царь судить – и пред взором его развеется зло.","9":"Кто же скажет: «Нет порока в моем сердце, от греха своего я очистился»?","10":"Взвесил, да обвесил; отмерил, да обмерил – мерзость все это для Господа.","11":"Смолоду человек познается по делам, чисты ли, честны ль его поступки.","12":"Ухо слышащее, око зрячее – то и другое создано Господом.","13":"Любишь поспать – дождешься нищеты; не смыкаешь глаз – наешься досыта.","14":"«Дрянной товар!» – говорит покупатель, а едва отойдет – давай хвалиться.","15":"Есть на свете золото, есть самоцветы, но сведущие уста драгоценнее.","16":"Кто за чужого поручился, в залог отдаст одежду, и такой же залог – за жену чужую.","17":"Сладок хлеб, добытый обманом, но во рту битым камнем обернется.","18":"Замысел зреет в обсуждениях: ведя войну, выслушивай советы.","19":"Кто распускает сплетни, тот и секреты выдаст, так что не связывайся с болтуном.","20":"Кто проклинает отца с матерью – погаснет его светильник во тьме кромешной.","21":"С жадностью схваченное наследство не обернется благословением.","22":"Не говори: «Отплачу за зло!» Доверься Господу, и Он защитит тебя.","23":"Гири с обманом – мерзость для Господа, и дурное дело – неверные весы.","24":"Господь направляет шаги человека. А человеку – как понять свой путь?","25":"Ловушка для человека – торопливая клятва или обет необдуманный.","26":"Мудрый царь развеет нечестивцев, колесом молотильным по ним проедет.","27":"Дух в человеке – светильник Господень, что просвечивает его насквозь.","28":"Вера и правда сберегают царя, верностью укрепляется престол.","29":"Юноши сияют силой, а старцев украшает седина.","30":"Раны и рубцы очищают от зла, исправляют побои нутро человека."},"21":{"1":"Сердце царя в руке Господа, как в русле вода – повернет его Господь, куда пожелает.","2":"На свой взгляд человек всегда прав, но Господь испытывает сердца.","3":"Поступающий праведно и справедливо угодней Господу, чем приносящий жертвы.","4":"Надменный взгляд, гордое сердце, светильник нечестивых – грех.","5":"Старания приводят человека к достатку, а суета – лишь к нужде.","6":"Кто добивается богатства ложью – гонится за пустотой, стремится к смерти.","7":"Злодеяния нечестивцев их же и погубят: ведь они отказались поступать справедливо.","8":"Путь обманщика петляет, а поступки непорочного честны.","9":"Лучше жить на краю крыши, чем делить кров со сварливой женой.","10":"Нечестивец жаждет зла и ближнего не щадит.","11":"Наглеца накажешь – простаки поумнеют, наставь мудрого, и возрастет его знание.","12":"Наблюдает праведник за домом нечестивых и лишает их силы – на беду им.","13":"Кто при жалобных криках затыкает уши, сам однажды завопит, но ему не ответят.","14":"Тайный подарок остудит гнев, взятка из-под полы – буйную ярость.","15":"Справедливость совершается на радость праведнику и на страх злодею.","16":"Кто сбился с пути разумения, в царстве теней успокоится.","17":"Кто любит веселье, не знает достатка, кто любит вино да умащения – не разбогатеет.","18":"Выкуп за праведника – нечестивец, и за честного – обманщик.","19":"Лучше жить в пустыне, чем с женой вздорной и сварливой.","20":"Не переводятся у мудреца ценные запасы, а глупец все проедает.","21":"Кто стремится к праведности и верности, найдет и жизнь, и праведность, и почет.","22":"Мудрец покорит город богатырей, обрушит твердыню их надежды.","23":"Кто языку не дает воли, себя от бед обережет.","24":"Дерзкий и надменный, кому имя – наглец, в дерзости своей необуздан.","25":"Желания лодыря его погубят, ведь руки его не хотят работать,","26":"день за днем он изнывает от желаний, а праведник раздает не жалея.","27":"Жертвы от нечестивых – мерзость, еще большая мерзость – приносимые со злым умыслом.","28":"Погибнет лжесвидетель, а последнее слово – за тем, кто все слышал.","29":"Нечестивец напускает на себя наглый вид, но честный твердо идет своим путем.","30":"И мудрость, и разум, и совет – ничто перед Господом.","31":"Готовят коня на день битвы, но победа – от Господа."},"22":{"1":"Доброе имя желанней богатства, любовь людей лучше золота и серебра.","2":"Богатый и бедный встанут рядом, ведь обоих сотворил Господь.","3":"Увидит умный беду – и скроется, простаки пойдут напрямик – и поплатятся.","4":"Следом за смирением, за страхом Господним – и богатство, и почет, и жизнь.","5":"На пути лжеца – шипы да сети, кто жизнью дорожит, не пойдет туда.","6":"Выведи юношу на верную дорогу – он и в старости с нее не свернет.","7":"Богатый правит бедными, и должник – раб заимодавцу.","8":"Кто сеет несправедливость, пожнет беду, и сгинет бич его ярости.","9":"Благословен добросердечный – кто делится хлебом с бедняком.","10":"Прогони наглеца – и уйдет раздор, утихнут ссоры и брань.","11":"Кто любит чистоту сердца и приятен в речах – будет близок царю.","12":"Господь оберегает истину, опровергнет Он слова отступника.","13":"Лодырь говорит: «Лев во дворе! Стоит из дому выйти – и я погиб».","14":"Уста чужой жены – глубокая западня, кто проклят Господом, туда упадет.","15":"Если у юноши дурь в голове – изгонит ее внушение розгой.","16":"Что угнетать бедняка ради корысти, что богачу давать – лишь убыток.","17":"Преклони ухо, слушай слова мудрецов, внимай моему наставлению:","18":"сладостно хранить слова эти в сердце, пусть всегда они будут на устах твоих;","19":"чтобы в Господе обрел ты упование, я тебе их сегодня возвещаю.","20":"Я написал тебе тридцать изречений, где найдешь ты совет и познание,","21":"чтоб научился ты словам истины и смог своим начальникам ответить.","22":"Не обирай бедняка, наживаясь на бедности, убогого у ворот не обижай,","23":"ибо Господь рассудит их жалобу, за их лишения – лишит тебя жизни.","24":"Не дружи с гневливым, со вспыльчивым не водись,","25":"а не то пойдешь по их стопам, и сам себе расставишь сети.","26":"Не спеши давать поруку, ручаться за чужие долги:","27":"ведь если нечем будет расплатиться, то даже постель твою отнимут!","28":"Не сдвигай старинной межи, которую отцы установили.","29":"Видел человека, искусного в работе? Он служит царям, а не черни."},"23":{"1":"Когда сядешь за стол с правителем – внимательно смотри, что пред тобою;","2":"приставь нож себе к горлу, если жаден ты до еды.","3":"Лакомствами его не прельщайся, обманчива эта пища.","4":"Не слишком гонись за богатством, знай, когда остановиться;","5":"только взглянешь на богатство, а его уж нет: приделало себе орлиные крылья да и улетело в небо.","6":"Не ешь с человеком, чей взор недобр, лакомствами его не прельщайся;","7":"ведь душа его – на замке. Скажет тебе: «Ешь и пей», но сердце его – не с тобою;","8":"проглоченный кусок отрыгнешь, добрые слова зря потратишь.","9":"Глупцу ничего не говори – над разумной речью он только посмеется.","10":"Не сдвигай старинной межи, на поле к сиротам не вторгайся;","11":"ведь у них могучий Заступник, Он и поведет их тяжбу.","12":"Сердцем обратись к поучению и прислушайся к словам знания.","13":"Не оставляй сына без внушения, посечешь его розгой – не умрет:","14":"ты высечешь его розгой – зато от погибели избавишь.","15":"Сын, если в твоем сердце мудрость – то и в моем будет радость,","16":"все во мне возликует, если будешь ты говорить верно.","17":"Пусть не завидует сердце твое грешникам, пусть всегда боится Господа,","18":"ибо наступит будущее, и твоя надежда не погибнет.","19":"Слушай, сын, и становись мудрым, на верный путь направь сердце.","20":"Не будь с теми, кто упивается вином да объедается мясом,","21":"ибо пьяница и обжора обнищают, а лень тебя вырядит в лохмотья.","22":"Слушайся отца, что породил тебя, а состарится мать – не презирай ее.","23":"Приобретай истину и не растеряй ни мудрости, ни воспитания, ни разума.","24":"Отец праведника возликует, родитель мудреца не нарадуется.","25":"Да возрадуются твои отец и мать, да возликуют твои родители!","26":"Сын! Ко мне обрати свое сердце, взор к моим путям направь.","27":"Блудница – что глубокая яма, чужая жена – что узкий колодец,","28":"она – что разбойник в засаде, умножает число преступлений.","29":"У кого это охи да вздохи? У кого это ссоры да жалобы? У кого синяки невесть откуда? У кого муть в глазах?","30":"У тех, кто засиживается за вином, все выискивает вина пряные.","31":"Не гляди на вино, как оно алеет, как в чаше играет, да как пьется легко;","32":"потом ведь укусит, как змея, ужалит, как гадюка;","33":"засмотришься тогда на чужих женщин, и придут на ум превратные мысли;","34":"словно ты улегся среди моря, на верхушке мачты улегся.","35":"«Били меня, – скажешь, – а мне нипочем, колотили – а я и не чувствовал; а уж как просплюсь, так примусь за старое»."},"24":{"1":"Не завидуй людям злым, не стремись стать одним из них,","2":"жестокие затеи у них на уме, их уста кому-то беду готовят.","3":"Мудростью возводится дом, разумением он прочен,","4":"а знание наполняет покои достатком драгоценным и желанным.","5":"Кто мудр, тот силен, кто обладает знанием, тот могуч.","6":"Ведя войну, выслушивай советы: победа там, где советников много.","7":"Мудрость для глупца недоступна, у ворот городских ему и рта не раскрыть.","8":"Кто замышляет зло, того прозовут коварным.","9":"Затеи глупца – грех, и мерзок людям наглец.","10":"Если в день беды ты пал духом – беден ты силой.","11":"Выручай ведомых на смерть, не отстраняйся от обреченных на гибель!","12":"Ты скажешь: «Мы же не знали об этом!» Но Испытующий сердца ведает, все знает Страж твоей жизни – Он каждому воздаст по заслугам.","13":"Сын мой, вкушай мед, ибо он хорош, ибо сладки соты для твоего рта.","14":"Такова и мудрость для души твоей, и если нашел ее – есть у тебя будущее, и надежды твои не погибнут.","15":"Нечестивец, не устраивай засад у дома праведника, обители его не разоряй:","16":"праведник семь раз упадет – но встанет, а нечестивые споткнутся – и беда им!","17":"Пал твой враг – не радуйся, споткнулся – пусть не ликует твое сердце,","18":"иначе увидит Господь, сочтет это злом и Свой гнев от твоего врага отведет.","19":"На злодеев не злись, нечестивым не завидуй,","20":"ибо у зла нет будущего, и светильник нечестивых погаснет.","21":"Бойся Господа, сын, и бойся царя, изменников сторонись,","22":"ибо беда придет от них внезапно: сам не знаешь, какое навлекут несчастье.","23":"Вот другие слова мудрецов. Пристрастный суд – недоброе дело;","24":"кто оправдывает нечестивца – проклят народами, отвергнут племенами.","25":"Но благо тем, кто его наказывает, снизойдет на них благословение.","26":"Верный ответ – что поцелуй в уста.","27":"Обустрой сперва двор, займись своим полем, а потом уже строй себе дом.","28":"Не свидетельствуй ложно против ближнего – пусть не будет на устах твоих обмана.","29":"Не говори: «Как он со мной поступил, так и я с ним, воздам ему по заслугам!»","30":"Проходил я раз мимо поля лодыря, мимо виноградника неразумного хозяина,","31":"так вот: повсюду разросся терновник, все заполонили сорняки, развалилась каменная ограда.","32":"Посмотрел я, поразмыслил, вот что увидел я и понял:","33":"еще чуть поспишь, подремлешь, еще посидишь сложа руки –","34":"и придет к тебе бедность, как бродяга, нагрянет нужда, как грабитель."},"25":{"1":"Вот другие притчи Соломона, сохраненные людьми Езекии, царя Иудеи.","2":"Славен Бог, тайное сокрывший; славен царь, тайное понявший.","3":"Небесную высь, земную глубь и сердце царя – не понять.","4":"Удали примесь из серебра, и выйдет у мастера чаша;","5":"удали нечестивца от царя, и праведностью престол утвердится.","6":"Не красуйся перед царем, в один ряд с вельможами не становись;","7":"лучше пусть скажут тебе: «Поднимись повыше», чем унизят тебя перед знатью. Что увидишь своими глазами,","8":"не торопись выносить на суд; а иначе – каково будет потом, когда посрамит тебя ближний?","9":"Судись с ближним лишь по собственному делу, чужой тайны не разглашай,","10":"а расскажешь – тебя же опозорят, и бесчестия тогда не миновать.","11":"Золотые яблоки на серебряном узоре – таково слово, сказанное ко времени.","12":"Золотая серьга, червонная подвеска – таков мудрый упрек для чуткого уха.","13":"Прохлада снега в разгар жатвы – таков для хозяина верный исполнитель, придаст он сил своему господину.","14":"Тучи да ветер, а дождя все нет – так и тот, кто впустую сулит подарки.","15":"Долготерпение убедит и властителя, мягкая речь проймет и твердолобого.","16":"Нашел мед – поешь досыта, но не объедайся до тошноты;","17":"не ходи к другу слишком часто, не то пресытится тобой до отвращения.","18":"Палица, меч, острая стрела – таков для ближнего лжесвидетель.","19":"Как от зуба гнилого, от ноги хромой – проку от неверного в день беды.","20":"Как в холодный день срывать одежду, как уксус лить на соду – так и песни петь тому, кто в горе.","21":"Если голоден твой враг – дай ему хлеба, если жаждет – напои водой:","22":"так сгребаешь ты угли ему на голову, а тебя вознаградит Господь.","23":"Северный ветер несет с собой ливни, а язык сплетника – озлобленные взгляды.","24":"Лучше жить на краю кровли, чем делить кров со сварливой женой.","25":"Как прохладная вода для измученной души – так и добрая весть с дальней стороны.","26":"Как загрязненный родник, оскверненный источник – так и праведник, дрожащий перед нечестивцем.","27":"Нехорошо объедаться медом или добиваться похвалы.","28":"Как разоренный город без ограды – так и человек, не владеющий собой."},"26":{"1":"Как снег среди лета, как дождь в пору жатвы, так и слава глупцу не пристала.","2":"Птица упорхнет, ласточка улетит, так напрасное проклятие пройдет мимо.","3":"Плеть – для коня, узда – для осла, а розга – для спины глупца.","4":"Не отвечай глупцу по – глупому, чтоб ты сам ему не уподобился.","5":"Отвечай глупцу по – глупому, чтоб он мудрым себе не показался.","6":"Сам себя подкосит и хлебнет горя тот, кто дела свои поручает глупцу.","7":"Что вихляние ног у хромого, то и притча в устах глупцов.","8":"Что к праще камень привязывать, то и почести глупцу воздавать.","9":"Что пьяница за терновник хватается, что глупец притчи изрекает.","10":"Словно лучник, ранящий всех подряд, – тот, кто на службу берет глупцов, кого попало.","11":"Как пес возвращается к своей рвоте, так и глупец упорствует в своей дури.","12":"Видел человека, что мнит себя мудрым? От глупца и то больше проку.","13":"Лодырь говорит: «Лев на дороге! Зверь по улицам рыщет!»","14":"Как дверь на петлях болтается, так и лодырь в постели ворочается.","15":"Запустит лодырь руку в блюдо, а пока до рта донесет – устанет.","16":"Лодырь мнит себя мудрей семерых, говорящих разумно.","17":"Что пса дергать за уши, то и походя влезать в чужую ссору.","18":"Как безумец мечет горящие стрелы и смерть,","19":"так и тот, кто обманул ближнего и говорит: «Я же пошутил!»","20":"Кончились дрова – и погас огонь, сплетника нет – и утих раздор.","21":"От углей – жар, от дров – огонь, а от речей сплетника – вражда.","22":"Речи сплетника – что лакомство, проникают в самое нутро человека.","23":"Как посеребренный горшок из глины, так и ласковые уста при злобном сердце.","24":"Льстива речь недоброжелателя, а в душе он лелеет козни;","25":"хоть и нежен его голос – не верь, семь мерзостей у него на сердце;","26":"за обманом его ненависть таится, но откроется перед людьми его злоба.","27":"Кто роет яму, сам в нее упадет, кто катит камень, сам под него угодит.","28":"Лжец ненавидит свою жертву, льстивые уста готовят беду."},"27":{"1":"Не хвались завтрашним днем, ты не знаешь, что он принесет.","2":"Пусть хвалит тебя другой, а не ты; не твои, а чужие уста.","3":"Камень тяжел, и песок нелегок, но выходки глупца еще тяжелее.","4":"Гнев жесток, безудержна ярость, но кто устоит перед завистью?","5":"Откровенный обличитель лучше молчащего друга.","6":"Любящий ранит – от чистого сердца, ненавистник целует – из лести.","7":"Кто пресытился, и медовые соты растопчет, а голодному и горькое покажется сладким.","8":"Как птица, выпорхнувшая из гнезда, так и человек, что покинул родные места.","9":"Сердце радо умащениям и благовониям, так приятен и душевный совет от друга.","10":"Не забывай ни своих друзей, ни друзей отца; случится беда – не ходи к родне: лучше сосед поблизости, чем брат вдалеке.","11":"Будь мудр, сын, и радуй мое сердце, и мне будет, что обидчикам ответить.","12":"Увидит умный беду – и скроется, простаки пойдут прямо – и поплатятся.","13":"Кто за чужого поручился, в залог отдаст одежду, и такой же залог – за жену чужую.","14":"Благословлять соседа во весь голос, с утра пораньше – все равно что проклинать.","15":"Как дождь в ненастный день, так и сварливая баба;","16":"унимать ее – что удерживать ветер или масло сжимать в ладони.","17":"Железо оттачивается железом, а человек – другими людьми.","18":"Кто ухаживает за смоковницей – вкусит ее плодов, а кто заботится о своем господине – узнает почет.","19":"Как лицо отражается в воде, так и сердце человеческое – в сердце.","20":"Ненасытны Шеол и Аваддон, так и глаза человека ненасытны.","21":"Как тигель для серебра и горнило для золота, так для человека – слова похвалы.","22":"Даже если толочь дурня в ступе пестом, вместе с зерном, дурь из него не вылущить.","23":"Всех своих овец знай наперечет, заботься о своих стадах;","24":"ибо никакие запасы не вечны, и даже венец не всегда наследуется.","25":"Увяла трава – но вот и новая зелень, скошены травы с горных лугов;","26":"ягнята – тебе на одежду, козлята – в уплату за поле,","27":"вдоволь козьего молока тебе в пищу, в пищу твоей семье, и чтоб были сыты служанки."},"28":{"1":"Бежит нечестивец, хотя никто за ним не гонится, а праведник невозмутим, как лев.","2":"Когда в стране смута, правителей много, но с правителем разумным и сведущим страна устоит.","3":"Бедняк, притесняющий нищих, – что ливень, смывающий посевы.","4":"Кто забыл о Законе – восхваляет нечестивцев, но кто хранит его, тот борется с ними.","5":"Злые люди не понимают справедливости, но ищущие Господа поймут ее сполна.","6":"Лучше бедняк, что живет непорочно, чем богач, чьи пути превратны.","7":"Разумный сын соблюдает Закон, а кто водится с беспутными – позорит отца.","8":"Ростовщик, что на ссудах наживается, копит для того, кто милостив к беднякам.","9":"Кто слов Закона слушать не хочет, у того и молитва – мерзость.","10":"Кто заманивает честных на путь зла, в свою же ловушку попадет, а кто непорочен – тому благая доля.","11":"Богач себя мудрецом воображает, но умный бедняк его раскусит.","12":"Радуются праведники – и царит ликование; возвышаются нечестивцы – и прячется человек.","13":"Скрываешь свой грех – добра не жди; признаешь его и отвергнешь – помилован будешь.","14":"Блажен, кто всегда страшится Господа, а жестокосердный попадет в беду.","15":"Лев рычащий, медведь свирепый – таков дурной правитель для бедного люда.","16":"Чем глупее правитель, тем больше поборов; но продлятся дни того, кто чужд корысти.","17":"Кто отягощен кровопролитием – пусть до могилы скитается, пусть не находит приюта.","18":"Кто живет непорочно, будет в безопасности, а кто ходит кривыми путями, нежданно упадет.","19":"Кто возделывает землю, будет сыт, а кто за пустотой гоняется, хлебнет нищеты.","20":"Стократ благословен человек верный, а кто рвется к богатству, не уйдет от возмездия.","21":"Пристрастность – дело недоброе: грешит человек ради ломтя хлеба.","22":"Алчный торопится обогатиться, но не знает, что ступает за ним нищета.","23":"Скорей отблагодарят тебя за упреки, чем за льстивые речи.","24":"Кто обирает отца с матерью, приговаривая: «Нет в том греха», – тот заодно с разбойниками.","25":"Корыстный человек затевает раздоры, а уповающий на Господа благоденствует.","26":"Кто только на себя надеется – глуп, а спасется тот, кто ходит путями мудрости.","27":"Кто делится с бедным, не знает недостатка, а кто закрывает глаза, умножает себе проклятия.","28":"Возвышаются нечестивцы – и прячется человек, погибают они – и множатся праведники."},"29":{"1":"Кто ожесточается, слыша наставления, погибнет нежданно и безвозвратно.","2":"Праведные в силе – и радуется народ; нечестивцы у власти – и народ стонет.","3":"Кто любит мудрость, радует отца своего, а кто знается с блудницами – расточает нажитое.","4":"Царское правосудие укрепляет страну, а взятки ее разрушают.","5":"Кто льстит ближнему, сеть ему стелет под ноги.","6":"Грех – ловушка для нечестивца, а праведник веселится и радуется.","7":"Помнит праведник о тяжбе бедняка, а нечестивый и знать не хочет.","8":"Наглые люди баламутят город, а мудрые утихомирят ярость.","9":"Если мудрец судится с глупцом – смятение и смех не стихают.","10":"Убийцы ненавидят непорочного и честного погубить стремятся.","11":"Глупец дает волю гневу, а мудрый дает ему остыть.","12":"Если правитель выслушивает ложь, то и придворные будут нечестивы.","13":"Вот что роднит бедняка и угнетателя: свет в очах у обоих – от Господа.","14":"Если царь судит бедных по правде – престол его нерушим вовеки.","15":"Розга и внушения дают мудрость, а заброшенный ребенок – позор для матери.","16":"Где сильны нечестивцы, силен и грех, но праведники увидят их падение.","17":"Вразумляй сына, и будешь за него спокоен, станет он для тебя утешением.","18":"Нет пророческих видений – и разнуздан народ, но блажен, кто соблюдает Закон.","19":"Словами раба не вразумить, хоть и поймет, да оставит без внимания.","20":"Видел ты человека, скорого на слова? От глупца и то больше проку.","21":"Если раба с детства баловать – добром это не кончится.","22":"Гневливый вызывает раздоры, вспыльчивый множит злодеяния.","23":"Заносчивый будет унижен, а смиренный обретет славу.","24":"Кто вору товарищ, тот сам себе враг: слышит, как проклинают вора, да помалкивает.","25":"Страх перед людьми – расставленные сети, но уповающий на Господа – неприступен.","26":"Многие ищут благосклонности правителя, но судья человеку – Господь.","27":"Мерзок праведникам обманщик, мерзок нечестивым честный человек."},"30":{"1":"Слова Агура, сына Яке, массаита. Вот что возвестил этот муж Итиэлу, Итиэлу и Ухалу.","2":"Конечно, я тупее всех людей, и нет во мне человеческого разумения,","3":"не выучился я мудрости и священному знанию непричастен.","4":"Кто взошел на небо и спустился? Кто удержал ветер в горсти? Кто завернул воду в накидку? Кто установил пределы земли? Как ему имя? Как имя его сыну? Ты, конечно, знаешь?","5":"Все речения Божьи непорочны и чисты; Он – Щит для прибегающих к Нему.","6":"Не прибавляй лишнего к Его словам, не то уличит тебя, и окажешься лжецом.","7":"О двух вещах прошу Тебя, не откажи в них, пока я жив:","8":"пустое и лживое слово удали от меня, не давай мне ни бедности, ни богатства, отмеряй мне мою долю хлеба;","9":"чтобы, пресытившись, я не отрекся, не сказал бы: «А кто это – Господь?» или, обнищав, не стал бы воровать, оскверняя имя Бога моего.","10":"Не клевещи на слугу перед его господином, не то падет на тебя его проклятие.","11":"Бывает, что проклинают отцов и матерей не благословляют;","12":"бывает, что мнят себя чистыми, но от собственного кала не омылись;","13":"бывает, что смотрят надменно, высоко возносят взоры;","14":"бывает, что зубы – как мечи, и челюсти – как ножи мясника, чтоб пожирать меж людьми бедных и обездоленных со свету сживать.","15":"У пиявки – две дочери: дай! дай! Три вещи никогда не насытятся, и четвертая не скажет «хватит!»:","16":"Шеол, бесплодное чрево, и земля, что никак не насытится водой, и огонь, что никогда не скажет «хватит!»","17":"Если око с насмешкой глядит на отца и мать ни во что не ставит – выклюет его ворон в долине, сожрет его стервятник.","18":"Три вещи меня поражают, и четвертой я не понимаю:","19":"пути орла в небесах, пути змеи на скале, пути корабля среди моря, пути мужчины к девушке.","20":"А путь развратницы таков: поест, губы утрет и скажет: «Ничего я худого не сделала».","21":"От трех вещей содрогается земля и четвертой вынести не может:","22":"раба, что стал царем, глупца, что досыта ест,","23":"позорную женщину, что вышла замуж, служанку, что заняла место госпожи.","24":"Есть на земле четверо малых, но они – мудрее мудрых:","25":"муравьи – народец слабосильный, а пищей запасаются с лета;","26":"зверьки – даманы – народец не могучий, а жилища устраивают среди скал;","27":"у саранчи нет царя, но выступает она единым строем;","28":"ящерица лапками цепляется, но бывает и в царских чертогах.","29":"У троих – статная осанка, и у четвертого – твердая поступь:","30":"у льва, богатыря среди зверей – никому дороги не уступит;","31":"у петуха – вожака, у козла, и у царя во главе войска.","32":"Если ты по глупости превознес сам себя, если замыслил недоброе – зажми себе ладонью рот,","33":"ибо от сбивания молока бывает масло, от битья по носу – кровь, а от биения гнева – вражда."},"31":{"1":"Слова Лемуэла, царя массаитов, которыми его поучала мать.","2":"Ну что, сынок? Что, сын моей утробы? Что, сын моих обетов?","3":"Не отдавай своей силы женщинам, не выдавай своих путей разорительницам царей.","4":"Не царям, Лемуэл, не царям пить вино, и не знати искать себе браги;","5":"не то упьются и законы забудут, и обездоленных лишат правосудия.","6":"Дайте браги тому, кто гибнет, и вина – кому горько на душе:","7":"выпьет – и забудет свою бедность, о несчастье своем не вспомнит.","8":"Говори за того, кто не может сказать, за права тех, кто бессилен;","9":"говори в защиту справедливости, ради прав нищего и несчастного.","10":"Как найти хорошую жену? Она дороже любых самоцветов,","11":"уверено в ней сердце мужа, с ней он без прибытка не останется,","12":"платит она ему добром, а не злом во все дни своей жизни.","13":"За шерсть ли берется, за лен ли – ищут работы ее руки.","14":"Она – как корабль торговый, пропитание добывает вдалеке.","15":"Еще ночь, а она уже встала – чтобы было чем кормить семью и чем занять служанок.","16":"Присмотрит поле и купит его, разведет виноградник, трудом добыв средства.","17":"Мощью опоясаны ее бедра, сила в ее руках.","18":"Видит, что хорошо идет торговля – и не гаснет в ночи ее светильник;","19":"руки ее тянутся к прялке, а пальцы не отпускают веретена;","20":"ладонь ее раскрыта для нищего, рука протянута несчастному.","21":"Снегопад семье ее не страшен – вся семья одета двойной тканью;","22":"и себе она мастерит наряды, в лен и шерсть багряную одета.","23":"Знают мужа ее у городских ворот, сидит он среди старейшин своей земли.","24":"Шьет она рубахи на продажу, пояса для купцов ханаанских.","25":"Облекается в силу и достоинство и радуется наступающему дню;","26":"на устах у нее – слово мудрости, наставления благие на языке;","27":"следит, как идут дела дома, и не напрасно ест свой хлеб.","28":"Встают дети и славят ее, муж ею не нахвалится:","29":"«Много было достойных женщин, но ты превзошла их всех!»","30":"Обаяние лживо, и пуста красота, но хвала жене, что боится Господа,","31":"воздайте же ей по заслугам, у ворот городских дела ее восхваляйте!"}};
